/* =====================================================================
 *  WORLD MAP GEOMETRY  (generated — do not hand-edit)
 * ---------------------------------------------------------------------
 *  Real country geometry from Natural Earth (via the `world-atlas`
 *  TopoJSON at 1:110m), projected equirectangular into a {W} x {H}
 *  viewBox and simplified for the web.
 *
 *  Because the projection is plain equirectangular, placing anything on
 *  the map is simple arithmetic:
 *      x = (lon + 180) / 360 * W
 *      y = (LAT_TOP - lat) / (LAT_TOP - LAT_BOT) * H
 *  which is exactly what `project()` below does. Antarctica is cropped
 *  (latitudes below {LAT_BOT}) because no student is flying in from there
 *  and it would waste a third of the canvas.
 * ===================================================================== */

export const MAP = { W: 1000, H: 389, LAT_TOP: 84, LAT_BOT: -56 } as const

/** Longitude/latitude to viewBox coordinates. */
export function project(lon: number, lat: number): { x: number; y: number } {
  return {
    x: ((lon + 180) / 360) * MAP.W,
    y: ((MAP.LAT_TOP - lat) / (MAP.LAT_TOP - MAP.LAT_BOT)) * MAP.H,
  }
}

